const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
let pos = 0;

const n = Number(input[pos++]);
const targetLength = Number(input[pos++]);
const words = [];

for (let i = 0; i < n; i++) words.push(input[pos++]);

const MOD = 998244353;
const BASE = 32768;

function mulMod(a, b) {
    const ah = Math.floor(a / BASE);
    const al = a - ah * BASE;
    const bh = Math.floor(b / BASE);
    const bl = b - bh * BASE;

    let r = ah * bh;
    r = (r * BASE + ah * bl + al * bh) % MOD;
    r = (r * BASE + al * bl) % MOD;
    return r;
}

function powMod(a, e) {
    let result = 1;
    while (e > 0) {
        if (e % 2 === 1) result = mulMod(result, a);
        a = mulMod(a, a);
        e = Math.floor(e / 2);
    }
    return result;
}

function inverseMod(a) {
    return powMod(a, MOD - 2);
}

// Build the dictionary trie.
const children = [new Map()];
const terminal = [false];

for (const word of words) {
    let node = 0;
    for (let i = 0; i < word.length; i++) {
        const c = word.charCodeAt(i) - 97;
        if (!children[node].has(c)) {
            const next = children.length;
            children[node].set(c, next);
            children.push(new Map());
            terminal.push(false);
        }
        node = children[node].get(c);
    }
    terminal[node] = true;
}

// NFA states are the root and trie nodes that can still be extended.
const trieToState = new Int32Array(children.length);
trieToState.fill(-1);
const stateToTrie = [0];
trieToState[0] = 0;

for (let node = 1; node < children.length; node++) {
    if (children[node].size > 0) {
        trieToState[node] = stateToTrie.length;
        stateToTrie.push(node);
    }
}

const q = stateToTrie.length;
const transitions = Array.from({ length: q }, () => []);

for (let state = 0; state < q; state++) {
    const trieNode = stateToTrie[state];

    for (const [letter, child] of children[trieNode]) {
        if (terminal[child]) {
            transitions[state].push([letter, 0]);
        }
        if (children[child].size > 0) {
            transitions[state].push([letter, trieToState[child]]);
        }
    }
}

// Construct only reachable states of the synchronized product automaton.
const pairId = new Map();
const pairA = [];
const pairB = [];
const graph = [];

function getPairId(a, b) {
    const key = a * q + b;
    let id = pairId.get(key);
    if (id === undefined) {
        id = pairA.length;
        pairId.set(key, id);
        pairA.push(a);
        pairB.push(b);
    }
    return id;
}

getPairId(0, 0);

for (let id = 0; id < pairA.length; id++) {
    const a = pairA[id];
    const b = pairB[id];
    const edgeWeights = new Map();

    for (const [letterA, nextA] of transitions[a]) {
        for (const [letterB, nextB] of transitions[b]) {
            if (letterA !== letterB) continue;

            const nextId = getPairId(nextA, nextB);
            edgeWeights.set(nextId, (edgeWeights.get(nextId) || 0) + 1);
        }
    }

    graph[id] = Array.from(edgeWeights.entries());
}

const stateCount = pairA.length;
const sequenceCount = 2 * stateCount + 5;
const sequence = new Array(sequenceCount);

let current = new Float64Array(stateCount);
current[0] = 1;

for (let length = 0; length < sequenceCount; length++) {
    sequence[length] = current[0];

    if (length + 1 === sequenceCount) break;

    const next = new Float64Array(stateCount);

    for (let state = 0; state < stateCount; state++) {
        const value = current[state];
        if (value === 0) continue;

        for (const [to, weight] of graph[state]) {
            next[to] += value * weight;
        }
    }

    for (let i = 0; i < stateCount; i++) {
        if (next[i] >= MOD) next[i] %= MOD;
    }

    current = next;
}

