function berlekampMassey(s) {
    let C = [1];
    let B = [1];
    let L = 0;
    let shift = 1;
    let lastDiscrepancy = 1;

    for (let index = 0; index < s.length; index++) {
        let discrepancy = s[index];

        for (let i = 1; i <= L; i++) {
            discrepancy += mulMod(C[i], s[index - i]);
        }
        discrepancy %= MOD;

        if (discrepancy === 0) {
            shift++;
            continue;
        }

        const oldC = C.slice();
        const coefficient = mulMod(discrepancy, inverseMod(lastDiscrepancy));
        const neededLength = B.length + shift;

        while (C.length < neededLength) C.push(0);

        for (let i = 0; i < B.length; i++) {
            const at = i + shift;
            let value = C[at] - mulMod(coefficient, B[i]);
            if (value < 0) value += MOD;
            C[at] = value;
        }

        if (2 * L <= index) {
            L = index + 1 - L;
            B = oldC;
            lastDiscrepancy = discrepancy;
            shift = 1;
        } else {
            shift++;
        }
    }

    const recurrence = new Array(L);
    for (let i = 0; i < L; i++) {
        recurrence[i] = C[i + 1] === 0 ? 0 : MOD - C[i + 1];
    }
    return recurrence;
}

