const order = recurrence.length;

function combinePolynomials(a, b) {
    const convolution = new Float64Array(2 * order - 1);

    for (let i = 0; i < order; i++) {
        if (a[i] === 0) continue;
        for (let j = 0; j < order; j++) {
            if (b[j] === 0) continue;
            convolution[i + j] += mulMod(a[i], b[j]);
