    for (let degree = 2 * order - 2; degree >= order; degree--) {
        const value = convolution[degree] % MOD;
        if (value === 0) continue;

        for (let j = 0; j < order; j++) {
            convolution[degree - 1 - j] += mulMod(value, recurrence[j]);
        }
    }

    const result = new Float64Array(order);
    for (let i = 0; i < order; i++) {
        result[i] = convolution[i] % MOD;
    }
    return result;
}

function linearRecurrenceTerm(k) {
    if (k < order) return sequence[k];

    let result = new Float64Array(order);
    result[0] = 1;

    let base = new Float64Array(order);
    if (order === 1) {
        base[0] = recurrence[0];
    } else {
        base[1] = 1;
