        if (k % 2 === 1) result = combinePolynomials(result, base);
        k = Math.floor(k / 2);
        if (k > 0) base = combinePolynomials(base, base);
    }

    let answer = 0;
    for (let i = 0; i < order; i++) {
        answer += mulMod(result[i], sequence[i]);
    }
    return answer % MOD;
}

