            shift++;
            continue;
        }

        const previousC = C.slice();
        const coefficient = mulMod(discrepancy, modInverse(lastDiscrepancy));

        while (C.length < B.length + shift) C.push(0);

        for (let i = 0; i < B.length; i++) {
            const index = i + shift;
            C[index] -= mulMod(coefficient, B[i]);
            if (C[index] < 0) C[index] += MOD;
        }

        if (2 * L <= pos) {
            L = pos + 1 - L;
            B = previousC;
            lastDiscrepancy = discrepancy;
            shift = 1;
        } else {
            shift++;
        }
    }

    const recurrence = new Array(L);
    for (let i = 0; i < L; i++) {
