const MOD = 998244353;
const BASE = 32768;

function mulMod(a, b) {
    const a0 = a % BASE;
    const a1 = (a - a0) / BASE;
    const b0 = b % BASE;
    const b1 = (b - b0) / BASE;

    let r = (a1 * b1) % MOD;
    r = (r * BASE + a1 * b0 + a0 * b1) % MOD;
    r = (r * BASE + a0 * b0) % MOD;
    return r;
}

function powMod(a, e) {
    let result = 1;
    while (e > 0) {
        if (e % 2 === 1) result = mulMod(result, a);
        a = mulMod(a, a);
        e = Math.floor(e / 2);
    }
    return result;
}

